// The four breathing exercises and the maths of one breath, ported from legacy/breathe.sh.
// Pure functions: no engine, no surface.

export type ExerciseKey = 'hrv' | 'sigh' | 'box' | '478';

export type Exercise = {
    key: ExerciseKey;
    name: string;
    /** The pattern, as the list prints it. */
    pattern: string;
    inhaleMs: number;
    hold1Ms: number;
    exhaleMs: number;
    hold2Ms: number;
    /** Physiological sigh: the first hold is a second, smaller inhale. */
    sip?: true;
};

export const EXERCISES: readonly Exercise[] = [
    {
        exhaleMs: 5500,
        hold1Ms: 0,
        hold2Ms: 0,
        inhaleMs: 5500,
        key: 'hrv',
        name: 'Coherent Breathing',
        pattern: '5.5s in, 5.5s out',
    },
    {
        exhaleMs: 10000,
        hold1Ms: 1000,
        hold2Ms: 0,
        inhaleMs: 4000,
        key: 'sigh',
        name: 'Physiological Sigh',
        pattern: 'double inhale, long exhale',
        sip: true,
    },
    {
        exhaleMs: 4000,
        hold1Ms: 4000,
        hold2Ms: 4000,
        inhaleMs: 4000,
        key: 'box',
        name: 'Box Breathing',
        pattern: '4s in, 4s hold, 4s out, 4s hold',
    },
    {
        exhaleMs: 8000,
        hold1Ms: 7000,
        hold2Ms: 0,
        inhaleMs: 4000,
        key: '478',
        name: '4-7-8 Breathing',
        pattern: '4s in, 7s hold, 8s out',
    },
];

const ALIASES: Record<string, ExerciseKey> = {
    '478': '478',
    box: 'box',
    coherence: 'hrv',
    coherent: 'hrv',
    hrv: 'hrv',
    physiological: 'sigh',
    relax: '478',
    sigh: 'sigh',
};

export const isExerciseKey = (value: unknown): value is ExerciseKey =>
    typeof value === 'string' && EXERCISES.some((e) => e.key === value);

/** The exercise a word names (`hrv`, `coherent`, `sigh`, `box`, `478`, `relax`), or undefined. */
export const resolveExercise = (word: string): ExerciseKey | undefined =>
    ALIASES[word.trim().toLowerCase()];

export const exerciseOf = (key: unknown): Exercise =>
    EXERCISES.find((e) => e.key === key) ?? EXERCISES[0]!;

export const cycleMs = (ex: Exercise): number =>
    ex.inhaleMs + ex.hold1Ms + ex.exhaleMs + ex.hold2Ms;

export type PhaseLabel = 'Breathe in' | 'Sip in' | 'Hold' | 'Breathe out';

export type Phase = {
    label: PhaseLabel;
    /** Milliseconds left in this phase. */
    remainingMs: number;
    /** How full the lungs are, 0..1000. */
    progress: number;
};

/** Ease-out (quadratic) over 0..1000: fast start, gentle deceleration. */
export const ease = (x: number): number => Math.floor((x * (2000 - x)) / 1000);

/** Where in the breath `elapsedMs` since the start lands. */
export function phaseAt(ex: Exercise, elapsedMs: number): Phase {
    const cycle = cycleMs(ex);
    const t = ((Math.floor(elapsedMs) % cycle) + cycle) % cycle;
    const inhaleEnd = ex.inhaleMs;
    const hold1End = inhaleEnd + ex.hold1Ms;
    const exhaleEnd = hold1End + ex.exhaleMs;

    if (t < inhaleEnd) {
        const eased = ease(Math.floor((t * 1000) / ex.inhaleMs));
        // a sigh's first inhale fills 85%; the sip takes the rest
        const progress = ex.sip ? Math.floor((eased * 850) / 1000) : eased;
        return { label: 'Breathe in', progress, remainingMs: inhaleEnd - t };
    }
    if (t < hold1End) {
        if (ex.sip) {
            const eased = ease(
                Math.floor(((t - inhaleEnd) * 1000) / ex.hold1Ms),
            );
            return {
                label: 'Sip in',
                progress: 850 + Math.floor((eased * 150) / 1000),
                remainingMs: hold1End - t,
            };
        }
        return { label: 'Hold', progress: 1000, remainingMs: hold1End - t };
    }
    if (t < exhaleEnd) {
        const eased = ease(Math.floor(((t - hold1End) * 1000) / ex.exhaleMs));
        return {
            label: 'Breathe out',
            progress: 1000 - eased,
            remainingMs: exhaleEnd - t,
        };
    }
    return { label: 'Hold', progress: 0, remainingMs: cycle - t };
}

/** The countdown the phase line shows: whole seconds, rounded up. */
export const secondsLeft = (phase: Phase): number =>
    Math.ceil(phase.remainingMs / 1000);

/** The spinner's word, which the engine follows with its own ellipsis: `Breathe in 4s` */
export const spinnerWord = (phase: Phase): string =>
    `${phase.label} ${secondsLeft(phase)}s`;

